arguments.command:
python3 - <<'EOF'
import json
cur=json.load(open('/workspace/repos/saleor-dashboard/package.json'))
tgt=json.load(open('/opt/environment/dependencies/target/saleor-dashboard/package.json'))
for section in ('dependencies','devDependencies'):
    c=cur.get(section,{}); t=tgt.get(section,{})
    only_c={k:v for k,v in c.items() if k not in t}
    only_t={k:v for k,v in t.items() if k not in c}
    changed={k:(c[k],t[k]) for k in c if k in t and c[k]!=t[k]}
    print(f"== {section}: only-current={len(only_c)} only-target={len(only_t)} changed={len(changed)}")
    for k,v in sorted(only_c.items()): print("  -C", k, v)
    for k,v in sorted(only_t.items()): print("  +T", k, v)
    for k,v in sorted(changed.items()): print("  ~", k, v[0], "=>", v[1])
# top-level fields
for k in set(list(cur)+list(tgt)):
    if k in ('dependencies','devDependencies'): continue
    cv=cur.get(k); tv=tgt.get(k)
    if cv!=tv:
        s=str(tv)
        print("FIELD", k, "| cur:", str(cv)[:120].replace('\n',' '), "| tgt:", s[:200].replace('\n',' '))
EOF

