# pnpm lock doesn't pin root version -> bumping package.json version doesn't break frozen-lockfile. But specifiers in lock must match package.json dep ranges. Verify sonner/specifiers in target lock match target package.json
python - <<'EOF'
import json, re
pkg = json.load(open('/opt/environment/dependencies/target/saleor-dashboard/package.json'))
want = {}
for sec in ('dependencies','devDependencies'):
    want.update(pkg.get(sec, {}))
import yaml
# pnpm lockfile v9 is yaml; check yaml lib present
try:
    import yaml
    ok=True
except ImportError:
    ok=False
print('yaml', ok)
if ok:
    lock = yaml.safe_load(open('/opt/environment/dependencies/target/saleor-dashboard/pnpm-lock.yaml'))
    root = lock['importers']['.']
    deps = {}
    deps.update(root.get('dependencies', {}) or {})
    deps.update(root.get('devDependencies', {}) or {})
    missing = []
    for name, spec in want.items():
        if name not in deps:
            missing.append((name, spec))
        elif deps[name]['specifier'] != spec:
            print('SPEC DIFF', name, spec, deps[name]['specifier'])
    print('missing from lock:', missing)
EOF

