arguments.command:
python - <<'EOF'
import csv
rows = list(csv.reader(open('/workspace/artifacts/sprint1/test-design/test-cases.v1.csv')))
header = rows[0]
print('header ok:', header == ['用例编号','一级模块','二级模块','用例标题','覆盖','优先级','前置条件','操作步骤','预期结果'])
print('rows:', len(rows)-1)
ids = [r[0] for r in rows[1:]]
print('unique ids:', len(set(ids)) == len(ids), ids[0], ids[-1])
import re
errs = []
for r in rows[1:]:
    if len(r) != 9: errs.append((r[0], 'cols', len(r)))
    if not re.match(r'^TC\d{3}$', r[0]): errs.append((r[0],'id'))
    if r[5] not in ('P0','P1','P2'): errs.append((r[0],'prio',r[5]))
    if not re.search(r'AC-\d{2}-\d', r[4]): errs.append((r[0],'AC missing'))
    if not re.match(r'^R\d{2} · ', r[2]): errs.append((r[0],'R title',r[2]))
# priority vs requirement priority
req_prio = {'R01':'P0','R02':'P0','R03':'P0','R04':'P0','R05':'P1','R06':'P0','R07':'P0','R08':'P1','R09':'P0','R10':'P1'}
for r in rows[1:]:
    rn = r[2].split(' ')[0]
    order = {'P0':0,'P1':1,'P2':2}
    if order[r[5]] > order[req_prio[rn]]:
        errs.append((r[0],'prio exceeds req', rn, r[5]))
print('errors:', errs if errs else 'none')
# module grouping check
mod = {'R01':'版本与发布标识','R02':'后端 API 与数据','R03':'后端 API 与数据','R04':'后端 API 与数据','R05':'后端 API 与数据','R06':'Dashboard 一致性','R07':'Dashboard 一致性','R08':'工程与交付保障','R09':'工程与交付保障','R10':'工程与交付保障'}
bad = [(r[0],r[1],r[2]) for r in rows[1:] if mod[r[2].split(' ')[0]] != r[1]]
print('module mismatches:', bad if bad else 'none')
# R titles copied verbatim from PRD
prd = open('/workspace/artifacts/sprint1/prd/prd.md').read()
import re as re2
titles = dict(re2.findall(r'#### (R\d{2} · [^\n]+)', prd))
bad = [r[0] for r in rows[1:] if r[2] != titles.get(r[2].split(' ')[0])]
print('R-title verbatim ok:', not bad, bad)
EOF

