    if not re.match(r'^TC\d{3}$', r[0]): errs.append((r[0],'id'))
    if r[5] not in ('P0','P1','P2'): errs.append((r[0],'prio',r[5]))
    if not re.search(r'AC-\d{2}-\d', r[4]): errs.append((r[0],'AC missing'))
req_prio = {'R01':'P0','R02':'P0','R03':'P0','R04':'P0','R05':'P1','R06':'P0','R07':'P0','R08':'P1','R09':'P0','R10':'P1'}
order = {'P0':0,'P1':1,'P2':2}
for r in rows[1:]:
    rn = r[2].split(' ')[0]
    # case must not be MORE strict than its requirement: case order index must be >= req index
    if order[r[5]] < order[req_prio[rn]]:
