# module grouping
mod = {'R01':'版本与发布标识','R02':'后端 API 与数据','R03':'后端 API 与数据','R04':'后端 API 与数据','R05':'后端 API 与数据','R06':'Dashboard 一致性','R07':'Dashboard 一致性','R08':'工程与交付保障','R09':'工程与交付保障','R10':'工程与交付保障'}
